'use strict';
// mysql2's connection hierarchy, reduced to its dispatch shape.
//
//   BaseConnection.end(callback)   -> implicit-generic (untyped param)
//   Connection extends BaseConnection   (declares no `end`)
//   PoolConnection extends Connection   -> OVERRIDES end(callback)
//
// The middle class is not decoration: `findGenericMethodOn` walks the base
// CHAIN, so the override's inherited declaration is two links up, and the
// subclass scan `genericOverrideBelow` runs has to recurse to see it.

class Base {
  constructor(name) {
    this.name = name;
    this.log = '';
  }

  // Implicit-generic: `callback` is untyped, never written, not optional.
  end(callback) {
    this.log += 'B';
    if (typeof callback === 'function') {
      callback('base:' + this.name);
    }
    return 'Base.end<' + this.name + '>';
  }

  // A SECOND untyped method nobody overrides — the control: it must keep
  // monomorphizing exactly as it did before, one instance per argument
  // tuple.
  tag(prefix) {
    return prefix + '/' + this.name;
  }

  // Zero parameters, so never implicit-generic: an ordinary vtable slot.
  describe() {
    return 'Base(' + this.name + ')';
  }
}

class Mid extends Base {}

class Pooled extends Mid {
  end(callback) {
    this.log += 'P';
    // `super.end` reaches the base's implicit-generic declaration, over
    // this method's own untyped `callback`.
    const inner = super.end(callback);
    return 'Pooled.end[' + inner + ']';
  }

  describe() {
    return 'Pooled(' + this.name + ')';
  }
}

// A parallel hierarchy where the override takes a DIFFERENT arity — the
// base declares one implicit param, the override two. Static dispatch
// resolves per receiver class, so each keeps its own signature.
class Wide extends Base {
  end(callback, extra) {
    return 'Wide.end[' + typeof callback + ',' + extra + ']';
  }
}

exports.Base = Base;
exports.Mid = Mid;
exports.Pooled = Pooled;
exports.Wide = Wide;
